referenceSolutions.python:
def duplicateCarriageThresholdFile(readings, k):
    a=readings
    out=[]
    write=0
    for read in range(len(a)):
        if write==0 or a[read]!=a[write-1]:
            a[write]=a[read]
            write+=1
    out=a[:write]
    return sum(x>=k for x in out)

